parameters.text:
=Build the full strategic marketing plan for this brief.

BRAND: {{ $("Normalize Brief").first().json.brand_name }}
INDUSTRY: {{ $("Normalize Brief").first().json.industry }}
PRODUCT / SERVICE: {{ $("Normalize Brief").first().json.product_description }}
TARGET MARKET: {{ $("Normalize Brief").first().json.target_market }}
TARGET AUDIENCE: {{ $("Normalize Brief").first().json.target_audience }}
OBJECTIVES: {{ $("Normalize Brief").first().json.objectives }}
MAIN NUMERIC GOAL: {{ $("Normalize Brief").first().json.goal_target || "not specified - propose one" }}
TOTAL BUDGET: {{ $("Normalize Brief").first().json.total_budget }} {{ $("Normalize Brief").first().json.currency }}
START DATE: {{ $("Normalize Brief").first().json.start_date }}
DURATION: {{ $("Normalize Brief").first().json.duration_months }} months (END DATE: {{ DateTime.fromISO($("Normalize Brief").first().json.start_date).plus({ months: Number($("Normalize Brief").first().json.duration_months) }).minus({ days: 1 }).toISODate() }}, TOTAL WEEKS: {{ Math.max(4, Math.round(Number($("Normalize Brief").first().json.duration_months) * 4.345)) }})
USP: {{ $("Normalize Brief").first().json.usp || "not specified - infer from the product" }}
COMPETITORS: {{ $("Normalize Brief").first().json.competitors || "not specified" }}
AVAILABLE CHANNELS: {{ $("Normalize Brief").first().json.available_channels }}
BRAND TONE: {{ $("Normalize Brief").first().json.brand_tone }}
EXTRA NOTES: {{ $("Normalize Brief").first().json.extra_notes || "none" }}

OUTPUT LANGUAGE: write every text value in {{ $("Normalize Brief").first().json.output_language === "English" ? "English" : "Arabic (Modern Standard, marketing-friendly; keep channel names and KPI acronyms like CPL, CTR, ROAS in English)" }}.

parameters.jsCode:
const p = $input.first().json.output || {};
const b = $('Normalize Brief').first().json;
const ar = String(b.output_language || '') !== 'English';
const esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
const arr = function (x) { return Array.isArray(x) ? x : []; };
const L = ar ? { plan: 'الخطة الاستراتيجية للتسويق', exec: 'الملخص التنفيذي', snap: 'نظرة سريعة', budget: 'الميزانية', duration: 'المدة', months: 'شهور', market: 'السوق', goal: 'الهدف', s1: '01 · التموضع والرسائل', segs: 'الشرائح المستهدفة', pain: 'نقاط الألم', pos: 'بيان التموضع', vp: 'القيمة المقدمة', diff: 'عوامل التميز', pillars: 'ركائز البراند', msgs: 'مصفوفة الرسائل', aud: 'الجمهور', msg: 'الرسالة', proof: 'الدليل', tags: 'مقترحات الشعار', tone: 'نبرة الصوت', s2: '02 · مزيج القنوات والميزانية', mix: 'توزيع الميزانية', channel: 'القناة', role: 'الدور', total: 'الإجمالي', tactics: 'دور كل قناة والتكتيكات', why: 'السبب', s3: '03 · تخطيط الحملات', camps: 'الحملات', idea: 'الفكرة', deliv: 'المخرجات', s4: '04 · الجدول الزمني والمراحل', cal: 'الجدول الزمني', mil: 'المحطات الرئيسية', owner: 'المسؤول', s5: '05 · مؤشرات الأداء والأهداف', kpis: 'مؤشرات الأداء والأهداف', kpi: 'المؤشر', stage: 'المرحلة', target: 'المستهدف', meas: 'طريقة القياس', freq: 'التكرار', risks: 'المخاطر', mit: 'التعامل', next: 'الخطوات التالية', wrap: 'الختام', m: 'ش', w: 'أ' } : { plan: 'Strategic Marketing Plan', exec: 'Executive summary', snap: 'Snapshot', budget: 'Budget', duration: 'Duration', months: 'months', market: 'Market', goal: 'Goal', s1: '01 · Positioning & messaging', segs: 'Target segments', pain: 'Pain points', pos: 'Positioning statement', vp: 'Value proposition', diff: 'Differentiators', pillars: 'Brand pillars', msgs: 'Messaging matrix', aud: 'Audience', msg: 'Message', proof: 'Proof point', tags: 'Tagline options', tone: 'Tone of voice', s2: '02 · Channel mix & budget', mix: 'Budget allocation', channel: 'Channel', role: 'Role', total: 'Total', tactics: 'Channel roles & tactics', why: 'Why', s3: '03 · Campaign planning', camps: 'Campaigns', idea: 'Big idea', deliv: 'Deliverables', s4: '04 · Calendar & milestones', cal: 'Campaign calendar', mil: 'Key milestones', owner: 'Owner', s5: '05 · KPIs & targets', kpis: 'KPIs & targets', kpi: 'KPI', stage: 'Stage', target: 'Target', meas: 'Measurement', freq: 'Frequency', risks: 'Risks', mit: 'Mitigation', next: 'Next steps', wrap: 'Wrap-up', m: 'M', w: 'W' };
const budget = Number(b.total_budget) || 0;
const cur = esc(b.currency || '');
const money = function (n) { return Math.round(n).toLocaleString('en-US') + ' ' + cur; };
const pos = p.positioning || {};
const channels = arr(p.channel_mix).slice();
const pctSum = channels.reduce(function (s, c) { return s + (Number(c.budget_percent) || 0); }, 0) || 1;
channels.forEach(function (c) { c.pct = (Number(c.budget_percent) || 0) * 100 / pctSum; c.amount = budget * c.pct / 100; });
channels.sort(function (x, y) { return y.pct - x.pct; });
const months = Number(b.duration_months) || 3;
const totalWeeks = Math.max(4, Math.round(months * 4.345));
const list = function (items) { return '<ul>' + arr(items).map(function (i) { return '<li>' + esc(i) + '</li>'; }).join('') + '</ul>'; };
const chips = function (items) { return '<div class="chips">' + arr(items).map(function (i) { return '<span class="chip">' + esc(i) + '</span>'; }).join('') + '</div>'; };
const slides = [];
const slide = function (kicker, title, body) { slides.push('<section class="slide"><div class="kicker">' + esc(kicker) + '</div><h2>' + esc(title) + '</h2><div class="body">' + body + '</div><footer><span>' + esc(b.brand_name) + ' · ' + esc(L.plan) + '</span><span class="num"></span></footer></section>'); };
const tile = function (label, value) { return '<div class="tile"><div class="tl">' + esc(label) + '</div><div class="tv">' + esc(value) + '</div></div>'; };
const table = function (heads, rows) { return '<table><thead><tr>' + heads.map(function (h) { return '<th>' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>' + rows.map(function (r) { return '<tr>' + r.map(function (c) { return '<td>' + c + '</td>'; }).join('') + '</tr>'; }).join('') + '</tbody></table>'; };

slides.push('<section class="slide cover"><div class="kicker">' + esc(L.plan) + '</div><h1>' + esc(b.brand_name) + '</h1><p class="lead">' + esc(b.industry) + ' · ' + esc(b.target_market) + '</p><p class="meta">' + esc(b.start_date) + ' · ' + months + ' ' + esc(L.months) + '</p></section>');
slide(L.snap, L.exec, '<p class="lead">' + esc(p.executive_summary) + '</p><div class="tiles">' + tile(L.budget, money(budget)) + tile(L.duration, months + ' ' + L.months) + tile(L.market, b.target_market) + tile(L.goal, b.goal_target || b.objectives) + '</div>');
slide(L.s1, L.segs, '<div class="grid g3">' + arr(pos.target_segments).map(function (s) { return '<div class="card"><h3>' + esc(s.name) + '</h3><p>' + esc(s.description) + '</p><div class="lbl">' + esc(L.pain) + '</div>' + list(s.pain_points) + '</div>'; }).join('') + '</div>');
slide(L.s1, L.pos, '<blockquote>' + esc(pos.positioning_statement) + '</blockquote><div class="grid g2"><div class="card"><div class="lbl">' + esc(L.vp) + '</div><p class="big">' + esc(pos.value_proposition) + '</p></div><div class="card"><div class="lbl">' + esc(L.diff) + '</div>' + list(pos.differentiators) + '</div></div>');
slide(L.s1, L.pillars, '<div class="grid g4">' + arr(pos.brand_pillars).map(function (x, i) { return '<div class="card pillar"><div class="pn">0' + (i + 1) + '</div><h3>' + esc(x.pillar) + '</h3><p>' + esc(x.description) + '</p></div>'; }).join('') + '</div><div class="grid g2"><div class="card"><div class="lbl">' + esc(L.tags) + '</div>' + chips(pos.tagline_options) + '</div><div class="card"><div class="lbl">' + esc(L.tone) + '</div><p>' + esc(pos.tone_of_voice) + '</p></div></div>');
slide(L.s1, L.msgs, table([L.aud, L.msg, L.proof], arr(pos.key_messages).map(function (k) { return ['<strong>' + esc(k.audience) + '</strong>', esc(k.message), esc(k.proof_point)]; })));
slide(L.s2, L.mix, '<div class="bars">' + channels.map(function (c) { return '<div class="bar-row"><div class="bn">' + esc(c.channel) + '<small>' + esc(c.funnel_role) + '</small></div><div class="track"><div class="fill" style="width:' + c.pct.toFixed(1) + '%"></div></div><div class="bp">' + Math.round(c.pct) + '%</div><div class="ba">' + money(c.amount) + '</div></div>'; }).join('') + '<div class="bar-row tot"><div class="bn">' + esc(L.total) + '</div><div></div><div class="bp">100%</div><div class="ba">' + money(budget) + '</div></div></div><p class="note">' + esc(p.budget_notes) + '</p>');
slide(L.s2, L.tactics, table([L.channel, L.role, L.why, L.tactics], channels.map(function (c) { return ['<strong>' + esc(c.channel) + '</strong>', '<span class="tag">' + esc(c.funnel_role) + '</span>', esc(c.rationale), list(c.tactics)]; })));
slide(L.s3, L.camps, '<div class="grid g2">' + arr(p.campaigns).map(function (c) { return '<div class="card camp"><div class="row"><span class="tag">' + esc(c.funnel_stage) + '</span><span class="wk">' + esc(L.w) + esc(c.start_week) + '–' + esc(L.w) + esc(c.end_week) + '</span></div><h3>' + esc(c.name) + '</h3><p><strong>' + esc(L.idea) + ':</strong> ' + esc(c.big_idea) + '</p><p class="q">“' + esc(c.key_message) + '”</p><p class="small">' + esc(c.objective) + ' · ' + esc(c.target_segment) + '</p>' + chips(c.channels) + '<div class="lbl">' + esc(L.deliv) + '</div>' + list(c.deliverables) + '</div>'; }).join('') + '</div>');

const monthMarks = [];
for (let m = 0; m < months; m++) { monthMarks.push('<span style="inset-inline-start:' + (m * 4.345 / totalWeeks * 100).toFixed(2) + '%">' + esc(L.m) + (m + 1) + '</span>'); }
const gantt = '<div class="gantt"><div class="g-head"><div></div><div class="g-scale">' + monthMarks.join('') + '</div></div>' + arr(p.campaigns).map(function (c) { const s = Math.min(Math.max(1, Number(c.start_week) || 1), totalWeeks); const e = Math.min(Math.max(s, Number(c.end_week) || s), totalWeeks); return '<div class="g-row"><div class="g-name">' + esc(c.name) + '</div><div class="g-track"><div class="g-bar" style="inset-inline-start:' + ((s - 1) / totalWeeks * 100).toFixed(2) + '%;width:' + ((e - s + 1) / totalWeeks * 100).toFixed(2) + '%">' + esc(L.w) + s + '–' + esc(L.w) + e + '</div></div></div>'; }).join('') + '</div>';
slide(L.s4, L.cal, gantt + '<div class="grid g' + Math.min(Math.max(arr(p.calendar).length, 2), 5) + '">' + arr(p.calendar).map(function (ph) { return '<div class="card"><div class="lbl">' + esc(ph.start_date) + ' → ' + esc(ph.end_date) + '</div><h3>' + esc(ph.phase) + '</h3><p class="small">' + esc(ph.focus) + '</p>' + list(ph.activities) + '</div>'; }).join('') + '</div>');
slide(L.s4, L.mil, '<ol class="timeline">' + arr(p.milestones).map(function (m) { return '<li><div class="td">' + esc(m.date) + '</div><div class="tm">' + esc(m.milestone) + '</div><div class="to">' + esc(L.owner) + ': ' + esc(m.owner) + '</div></li>'; }).join('') + '</ol>');
slide(L.s5, L.kpis, table([L.kpi, L.stage, L.target, L.meas, L.freq], arr(p.kpis).map(function (k) { return ['<strong>' + esc(k.kpi) + '</strong>', '<span class="tag">' + esc(k.stage) + '</span>', '<span class="target">' + esc(k.target) + '</span>', esc(k.measurement), esc(k.frequency)]; })));
slide(L.wrap, L.risks + ' · ' + L.next, '<div class="grid g2"><div class="card"><div class="lbl">' + esc(L.risks) + '</div>' + arr(p.risks).map(function (r) { return '<div class="risk"><strong>' + esc(r.risk) + '</strong><p>' + esc(L.mit) + ': ' + esc(r.mitigation) + '</p></div>'; }).join('') + '</div><div class="card"><div class="lbl">' + esc(L.next) + '</div><ol class="steps">' + arr(p.next_steps).map(function (s) { return '<li>' + esc(s) + '</li>'; }).join('') + '</ol></div></div>');

const css = ':root{--ink:#0f172a;--muted:#64748b;--line:#e2e8f0;--paper:#fff;--bg:#e8ebf2;--accent:#4338ca;--accent2:#0ea5a4;--soft:#eef2ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Cairo,Inter,system-ui,sans-serif;counter-reset:s}'
 + '.slide{counter-increment:s;position:relative;width:min(1280px,100% - 32px);min-height:720px;margin:24px auto;background:var(--paper);border-radius:18px;padding:56px 64px 72px;box-shadow:0 10px 30px rgba(15,23,42,.08);display:flex;flex-direction:column}'
 + '.kicker{color:var(--accent);font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:14px}h2{font-size:38px;margin:6px 0 24px;line-height:1.2}h1{font-size:72px;margin:12px 0;line-height:1.1}h3{margin:4px 0 8px;font-size:19px}p{margin:0 0 10px;line-height:1.6}.body{flex:1;display:flex;flex-direction:column;gap:20px}'
 + '.cover{justify-content:center;background:linear-gradient(135deg,#1e1b4b,#4338ca 60%,#0ea5a4);color:#fff}.cover .kicker{color:#c7d2fe}.cover .lead{font-size:26px;opacity:.9}.cover .meta{opacity:.75;font-size:18px}'
 + '.lead{font-size:21px;line-height:1.7}.note{color:var(--muted);font-size:15px}.small{font-size:14px;color:var(--muted)}.big{font-size:20px;font-weight:600}'
 + '.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.tile{background:var(--soft);border-radius:14px;padding:18px}.tl{font-size:13px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}.tv{font-size:22px;font-weight:700;margin-top:6px}'
 + '.grid{display:grid;gap:16px}.g2{grid-template-columns:repeat(2,1fr)}.g3{grid-template-columns:repeat(3,1fr)}.g4{grid-template-columns:repeat(4,1fr)}.g5{grid-template-columns:repeat(5,1fr)}'
 + '.card{border:1px solid var(--line);border-radius:14px;padding:18px 20px;background:#fff}.lbl{font-size:12px;font-weight:700;color:var(--accent);text-transform:uppercase;letter-spacing:.05em;margin:6px 0}.card ul,.card ol{margin:4px 0 0;padding-inline-start:18px}.card li{margin:3px 0;font-size:15px;line-height:1.5}'
 + '.pillar .pn{font-size:30px;font-weight:800;color:var(--accent2)}blockquote{margin:0;padding:22px 26px;border-inline-start:6px solid var(--accent);background:var(--soft);border-radius:12px;font-size:21px;line-height:1.7;font-weight:600}'
 + '.chips{display:flex;flex-wrap:wrap;gap:8px;margin:6px 0}.chip{background:var(--soft);color:var(--accent);border-radius:999px;padding:5px 12px;font-size:14px;font-weight:600}.tag{display:inline-block;background:#ccfbf1;color:#0f766e;border-radius:6px;padding:2px 8px;font-size:12px;font-weight:700}'
 + 'table{width:100%;border-collapse:collapse;font-size:15px}th{text-align:start;background:var(--ink);color:#fff;padding:10px 12px;font-size:13px;text-transform:uppercase;letter-spacing:.04em}td{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top;line-height:1.5}td ul{margin:0;padding-inline-start:16px}.target{font-weight:800;color:var(--accent)}'
 + '.bars{display:flex;flex-direction:column;gap:12px}.bar-row{display:grid;grid-template-columns:230px 1fr 60px 170px;gap:14px;align-items:center}.bn{font-weight:700}.bn small{display:block;font-weight:400;color:var(--muted);font-size:12px}.track{height:22px;background:var(--soft);border-radius:999px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,var(--accent),var(--accent2));border-radius:999px}.bp{font-weight:800;text-align:end}.ba{text-align:end;color:var(--muted);font-variant-numeric:tabular-nums}.tot{border-top:2px solid var(--ink);padding-top:10px}.tot .ba{color:var(--ink);font-weight:800}'
 + '.camp .row{display:flex;justify-content:space-between;align-items:center}.wk{font-size:13px;color:var(--muted);font-weight:700}.q{font-style:italic;color:var(--accent)}'
 + '.gantt{border:1px solid var(--line);border-radius:14px;padding:14px 18px}.g-head,.g-row{display:grid;grid-template-columns:220px 1fr;gap:14px;align-items:center}.g-row{margin-top:10px}.g-scale{position:relative;height:20px;border-bottom:1px solid var(--line)}.g-scale span{position:absolute;font-size:12px;color:var(--muted);font-weight:700}.g-name{font-weight:700;font-size:14px}.g-track{position:relative;height:28px;background:var(--soft);border-radius:6px}.g-bar{position:absolute;top:3px;bottom:3px;background:linear-gradient(90deg,var(--accent),var(--accent2));color:#fff;border-radius:6px;font-size:11px;font-weight:700;display:flex;align-items:center;padding:0 8px;white-space:nowrap;overflow:hidden}'
 + '.timeline{list-style:none;margin:0;padding:0;display:grid;gap:12px}.timeline li{display:grid;grid-template-columns:140px 1fr 260px;gap:16px;align-items:center;padding:14px 18px;border:1px solid var(--line);border-inline-start:6px solid var(--accent2);border-radius:12px}.td{font-weight:800;color:var(--accent)}.tm{font-weight:600}.to{color:var(--muted);font-size:14px}'
 + '.risk{padding:8px 0;border-bottom:1px dashed var(--line)}.risk p{font-size:14px;color:var(--muted);margin:4px 0 0}.steps li{font-size:16px;margin:8px 0}'
 + 'footer{position:absolute;bottom:22px;inset-inline:64px;display:flex;justify-content:space-between;font-size:12px;color:var(--muted)}.num::after{content:counter(s)}.cover footer{display:none}'
 + '@media (max-width:900px){.slide{padding:32px 20px 64px;min-height:auto}.g2,.g3,.g4,.g5,.tiles{grid-template-columns:1fr}.bar-row{grid-template-columns:1fr 50px}.bar-row .track,.bar-row .ba{grid-column:1/-1}.timeline li,.g-head,.g-row{grid-template-columns:1fr}h1{font-size:44px}h2{font-size:28px}footer{inset-inline:20px}}'
 + '@media print{@page{size:1280px 720px;margin:0}body{background:#fff}.slide{width:1280px;height:720px;min-height:0;margin:0;border-radius:0;box-shadow:none;break-after:page;overflow:hidden}.hint{display:none}}'
 + '.hint{position:fixed;bottom:14px;inset-inline-end:16px;background:var(--ink);color:#fff;font-size:12px;padding:6px 10px;border-radius:8px;opacity:.8}';
const nav = 'document.addEventListener("keydown",function(e){var s=[].slice.call(document.querySelectorAll(".slide"));var y=window.scrollY+20;var i=0;s.forEach(function(el,k){if(el.offsetTop<=y)i=k;});var d=0;if(["ArrowDown","ArrowRight","PageDown"," "].indexOf(e.key)>-1)d=1;if(["ArrowUp","ArrowLeft","PageUp"].indexOf(e.key)>-1)d=-1;if(d){e.preventDefault();var n=s[Math.min(Math.max(i+d,0),s.length-1)];window.scrollTo({top:n.offsetTop-12,behavior:"smooth"});}});';
const hint = ar ? 'استخدم الأسهم للتنقل · Ctrl+P للحفظ PDF' : 'Arrow keys to navigate · Ctrl+P to save as PDF';
const html = '<!DOCTYPE html><html lang="' + (ar ? 'ar' : 'en') + '" dir="' + (ar ? 'rtl' : 'ltr') + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(b.brand_name) + ' – ' + esc(L.plan) + '</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><style>' + css + '</style></head><body>' + slides.join('') + '<div class="hint">' + hint + '</div><script>' + nav + '</' + 'script></body></html>';
const slug = String(b.brand_name || 'brand').replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'brand';
return [{ json: { brand_name: b.brand_name, slides: slides.length, plan: p }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'Strategic-Plan-' + slug + '.html', fileExtension: 'html' } } }];
